def main():
    OUT.mkdir(parents=True,exist_ok=True)
    archives=read_csv(RAW/'archive_summary_raw.csv'); surfaces=read_csv(RAW/'surface_accountability_raw.csv'); dirs=read_csv(RAW/'directory_merkle_raw.csv'); defs=read_csv(RAW/'definition_index_raw.csv'); syms=read_csv(RAW/'symlinks_normalized_raw.csv')
    assert len(archives)==len(DONORS)==4
    assert {r['donor'] for r in surfaces}==set(DONORS)
    focus=focus_specs()
    # Validate focus donor paths now; target references may be generated later in this same cycle.
    for f in focus:
        p=donor_root(f['donor'])/f['path']
        if not p.is_file(): raise RuntimeError(f"focused donor path missing: {f['donor']}:{f['path']}")
    # Baseline inventory is embedded byte-for-byte for successor proof.
    shutil.copyfile(BASELINE,OUT/'post-refactor-232-baseline-files.csv')
    shutil.copyfile(RAW/'archive_summary_raw.csv',OUT/'post-refactor-232-archive-accountability.csv')
    write_csv(OUT/'post-refactor-232-directories.csv',dirs,list(dirs[0].keys()) if dirs else ['donor','directory','tree_sha256'])
    write_csv(OUT/'post-refactor-232-symbols.csv',defs,list(defs[0].keys()) if defs else ['donor','path','sha256','line','kind','symbol','snippet'])
    write_csv(OUT/'post-refactor-232-symlinks.csv',syms,list(syms[0].keys()) if syms else ['donor','path','target','mode','module'])

    bymodule=defaultdict(list)
    for r in surfaces:bymodule[(r['donor'],r['module'])].append(r)
    repo_id={d:f"PR232-R{i+1:03d}" for i,d in enumerate(DONORS)}
    modkeys=sorted(bymodule); mod_id={k:f"PR232-M{i+1:04d}" for i,k in enumerate(modkeys)}
    filekeys=sorted((r['donor'],r['path']) for r in surfaces); file_id={k:f"PR232-F{i+1:05d}" for i,k in enumerate(filekeys)}
    focus_id={i:f"PR232-S{i+1:03d}" for i in range(len(focus))}
    focus_by_path=defaultdict(list)
    for i,f in enumerate(focus):focus_by_path[(f['donor'],f['path'])].append(focus_id[i])

    module_rows=[]
    for d,m in modkeys:
        rows=bymodule[(d,m)]; layers=sorted({r['classification'] for r in rows})
        h=hashlib.sha256()
        for r in sorted(rows,key=lambda x:x['path']):h.update(f"{r['path']}\0{r['sha256']}\0{r['classification']}\n".encode())
        ids=[]
        for r in rows:ids += focus_by_path.get((d,r['path']),[])
        outcome='focused-adoption-or-guardrail' if ids else ('reviewed-target-fit' if any(r['classification'] in HIGH for r in rows) else 'accounted-reference')
        module_rows.append(dict(wave='232',donor=d,module=m,surfaces=len(rows),high_signal_surfaces=sum(r['classification'] in HIGH for r in rows),ui_product_surfaces=sum(r['classification']=='ui-or-product' for r in rows),implementation_surfaces=sum(r['classification']=='implementation' for r in rows),test_surfaces=sum(r['classification']=='test' for r in rows),layers=';'.join(layers),current_outcome=outcome,current_product_surfaces='Operations/Profiles where focused; otherwise governance',surface_sha256=h.hexdigest()))
    write_csv(OUT/'post-refactor-232-module-audit.csv',module_rows,list(module_rows[0].keys()))

    ledger=[]
    for d in DONORS:
        first=next(r for r in surfaces if r['donor']==d)
